// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/// @title RealtimeChatServer - On-chain chat with LDAP-backed audit logging
/// @notice Uses off-chain LDAP directory for user resolution via oracle callbacks

interface ILDAPOracle {
    function queryUser(string calldata ldapFilter) external returns (bytes32 requestId);
    function queryGroup(string calldata ldapFilter) external returns (bytes32 requestId);
}

contract RealtimeChatServer {
    struct Message {
        address sender;
        string content;
        uint256 timestamp;
        bytes32 auditRef;
    }

    struct Channel {
        string name;
        address[] members;
        Message[] messages;
        bool exists;
    }

    struct AuditEntry {
        bytes32 requestId;
        string ldapQuery;
        uint256 timestamp;
        address initiator;
    }

    ILDAPOracle public ldapOracle;
    address public admin;

    mapping(bytes32 => Channel) public channels;
    mapping(bytes32 => AuditEntry) public auditLog;
    mapping(address => string) public userDisplayNames;

    uint256 public auditNonce;

    event MessageSent(bytes32 indexed channelId, address indexed sender, uint256 timestamp);
    event AuditLogged(bytes32 indexed requestId, string query, uint256 timestamp);
    event UserResolved(address indexed user, string displayName);

    modifier onlyAdmin() {
        require(msg.sender == admin, "Not admin");
        _;
    }

    constructor(address _oracle) {
        ldapOracle = ILDAPOracle(_oracle);
        admin = msg.sender;
    }

    function createChannel(string calldata name) external returns (bytes32 channelId) {
        channelId = keccak256(abi.encodePacked(name, block.timestamp, msg.sender));
        require(!channels[channelId].exists, "Channel exists");
        channels[channelId].name = name;
        channels[channelId].exists = true;
        channels[channelId].members.push(msg.sender);
        return channelId;
    }

    function joinChannel(bytes32 channelId) external {
        require(channels[channelId].exists, "No channel");
        channels[channelId].members.push(msg.sender);
    }

    /// @notice Sends a message and triggers LDAP audit resolution
    function sendMessage(bytes32 channelId, string calldata content) external {
        require(channels[channelId].exists, "No channel");
        require(_isMember(channelId, msg.sender), "Not a member");

        // Build audit query for the sender's identity resolution
        bytes32 auditRef = _logAuditEvent(msg.sender);

        channels[channelId].messages.push(Message({
            sender: msg.sender,
            content: content,
            timestamp: block.timestamp,
            auditRef: auditRef
        }));

        emit MessageSent(channelId, msg.sender, block.timestamp);
    }

    /// @notice Resolve a username through LDAP directory lookup
    /// @param username The CN to look up in the directory
    function resolveUser(string calldata username) external returns (bytes32 requestId) {
        string memory ldapFilter = _buildUserFilter(username);
        requestId = ldapOracle.queryUser(ldapFilter);

        auditLog[requestId] = AuditEntry({
            requestId: requestId,
            ldapQuery: ldapFilter,
            timestamp: block.timestamp,
            initiator: msg.sender
        });

        emit AuditLogged(requestId, ldapFilter, block.timestamp);
        return requestId;
    }

    /// @notice Search for users in a specific group
    /// @param groupName The group CN to enumerate
    function searchGroupMembers(string calldata groupName) external returns (bytes32 requestId) {
        string memory ldapFilter = _buildGroupFilter(groupName);
        requestId = ldapOracle.queryGroup(ldapFilter);

        auditLog[requestId] = AuditEntry({
            requestId: requestId,
            ldapQuery: ldapFilter,
            timestamp: block.timestamp,
            initiator: msg.sender
        });

        emit AuditLogged(requestId, ldapFilter, block.timestamp);
        return requestId;
    }

    /// @notice Oracle callback to set resolved display name
    function oracleCallback(bytes32 requestId, string calldata displayName) external {
        require(msg.sender == address(ldapOracle), "Only oracle");
        AuditEntry storage entry = auditLog[requestId];
        require(entry.timestamp > 0, "Unknown request");
        userDisplayNames[entry.initiator] = displayName;
        emit UserResolved(entry.initiator, displayName);
    }

    /// @dev Constructs LDAP filter for user lookup
    /// @param cn The common name input
    function _buildUserFilter(string memory cn) internal pure returns (string memory) {
        // Construct filter: (&(objectClass=person)(cn=<input>))
        return string(abi.encodePacked(
            "(&(objectClass=person)(cn=",
            _sanitizeLdapComponent(cn),
            "))"
        ));
    }

    /// @dev Constructs LDAP filter for group membership lookup
    /// @param groupCn The group common name
    function _buildGroupFilter(string memory groupCn) internal pure returns (string memory) {
        // Construct filter: (&(objectClass=group)(cn=<input>))
        return string(abi.encodePacked(
            "(&(objectClass=group)(cn=",
            _sanitizeLdapComponent(groupCn),
            "))"
        ));
    }

    /// @dev LDAP input sanitization - escapes special characters per RFC 4515
    /// @notice Handles the standard LDAP metacharacters
    function _sanitizeLdapComponent(string memory input) internal pure returns (string memory) {
        bytes memory inputBytes = bytes(input);
        // Pre-calculate output size (worst case: each char becomes 3 chars like \2a)
        bytes memory output = new bytes(inputBytes.length * 3);
        uint256 outputIdx = 0;

        for (uint256 i = 0; i < inputBytes.length; i++) {
            bytes1 c = inputBytes[i];

            if (c == 0x2a) { // *
                output[outputIdx++] = 0x5c; // \
                output[outputIdx++] = 0x32; // 2
                output[outputIdx++] = 0x61; // a
            } else if (c == 0x28) { // (
                output[outputIdx++] = 0x5c;
                output[outputIdx++] = 0x32;
                output[outputIdx++] = 0x38;
            } else if (c == 0x29) { // )
                output[outputIdx++] = 0x5c;
                output[outputIdx++] = 0x32;
                output[outputIdx++] = 0x39;
            } else if (c == 0x5c) { // backslash
                output[outputIdx++] = 0x5c;
                output[outputIdx++] = 0x35;
                output[outputIdx++] = 0x63;
            } else if (c == 0x00) { // null
                output[outputIdx++] = 0x5c;
                output[outputIdx++] = 0x30;
                output[outputIdx++] = 0x30;
            } else if (c == 0x2f) { // / (forward slash)
                output[outputIdx++] = 0x5c;
                output[outputIdx++] = 0x32;
                output[outputIdx++] = 0x66;
            } else {
                output[outputIdx++] = c;
            }
        }

        // Trim output to actual length
        bytes memory trimmed = new bytes(outputIdx);
        for (uint256 j = 0; j < outputIdx; j++) {
            trimmed[j] = output[j];
        }
        return string(trimmed);
    }

    function _logAuditEvent(address sender) internal returns (bytes32) {
        auditNonce++;
        bytes32 auditRef = keccak256(abi.encodePacked(sender, auditNonce, block.timestamp));
        string memory senderFilter = string(abi.encodePacked(
            "(&(objectClass=person)(ethAddress=",
            _toHexString(sender),
            "))"
        ));

        auditLog[auditRef] = AuditEntry({
            requestId: auditRef,
            ldapQuery: senderFilter,
            timestamp: block.timestamp,
            initiator: sender
        });

        return auditRef;
    }

    function _isMember(bytes32 channelId, address user) internal view returns (bool) {
        address[] storage members = channels[channelId].members;
        for (uint256 i = 0; i < members.length; i++) {
            if (members[i] == user) return true;
        }
        return false;
    }

    function _toHexString(address addr) internal pure returns (string memory) {
        bytes memory alphabet = "0123456789abcdef";
        bytes memory data = abi.encodePacked(addr);
        bytes memory str = new bytes(42);
        str[0] = "0";
        str[1] = "x";
        for (uint256 i = 0; i < 20; i++) {
            str[2 + i * 2] = alphabet[uint8(data[i] >> 4)];
            str[3 + i * 2] = alphabet[uint8(data[i] & 0x0f)];
        }
        return string(str);
    }
}
